package ro.leo.visual;
import ro.leo.i18n.L;import java.io.*;import java.util.*;
public final class ZipActivity extends PocketActivity {
 private File selected,last;
 protected void render(){String incoming=getIntent().getStringExtra("zip_file");if(incoming!=null){getIntent().removeExtra("zip_file");File file=new File(incoming);try{if(!PocketStore.readable(this,file))throw new IOException("Unreadable ZIP");open(file);}catch(Exception e){problem(e);}return;}list(L.t("Arhive ZIP"),Arrays.asList(L.t("Deschide arhivă ZIP"),L.t("Creează ZIP dintr-un fișier"),L.t("Arhive și extrageri salvate"),L.t("Locație de salvare")),0,new Choice(){public void pick(int at){if(at==0)chooseFile("zip",1);else if(at==1)chooseFile("*",2);else if(at==3)startActivity(new android.content.Intent(ZipActivity.this,StorageSettingsActivity.class));else try{startActivity(new android.content.Intent(ZipActivity.this,FilesActivity.class).putExtra("folder",PocketStore.folder(ZipActivity.this,"Archives").getPath()));}catch(Exception e){problem(e);}}},"",null);}
 protected void selectedFile(int request,final File file){if(request==2){job(L.t("Creez arhiva"),new Work(){public void run()throws Exception{last=PocketStore.output(ZipActivity.this,"Archives",file.getName()+".zip");PocketZip.create(file,last);}},new Runnable(){public void run(){exported(last);}});}else open(file);}
 private void open(final File file){selected=file;final ArrayList<String> labels=new ArrayList<>();job(L.t("Verific arhiva"),new Work(){public void run()throws Exception{labels.addAll(PocketZip.list(file));}},new Runnable(){public void run(){list(file.getName(),labels,0,new Choice(){public void pick(int at){page(L.t("Intrare ZIP"),labels.get(at),goHome(),"",null);}},L.t("Extrage"),new Runnable(){public void run(){options(L.t("Extragi într-un folder nou?"),new String[]{L.t("Anulează"),L.t("Extrage")},new Choice(){public void pick(int yes){if(yes==1)job(L.t("Extrag arhiva"),new Work(){public void run()throws Exception{last=PocketStore.output(ZipActivity.this,"Archives","extracted");PocketZip.extract(file,last);}},new Runnable(){public void run(){startActivity(new android.content.Intent(ZipActivity.this,FilesActivity.class).putExtra("folder",last.getPath()));home();}});}});}});back=goHome();}});}
}
